-- Durable inspection only until one separately approved existing core RMA transition.
CREATE TABLE return_assistant_sessions (
 id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants,return_id uuid NOT NULL,order_id uuid NOT NULL,station_id uuid NOT NULL,station jsonb NOT NULL,
 actor_id uuid NOT NULL REFERENCES users,api_key_id uuid,client_key uuid NOT NULL,request_hash text NOT NULL,
 state text NOT NULL DEFAULT 'active' CHECK(state IN('active','completed','cancelled')),version bigint NOT NULL DEFAULT 1 CHECK(version>0),lease_generation bigint NOT NULL DEFAULT 1,
 lease_token_hash text NOT NULL,lease_expires_at timestamptz NOT NULL,source jsonb NOT NULL,scanned jsonb NOT NULL DEFAULT '[]',draft jsonb NOT NULL DEFAULT '{"parts":[],"note":"","shipping_refund":0}',
 created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 UNIQUE(tenant_id,id),UNIQUE(tenant_id,id,return_id),UNIQUE(tenant_id,client_key),
 FOREIGN KEY(tenant_id,order_id,return_id) REFERENCES return_cases(tenant_id,order_id,id),FOREIGN KEY(tenant_id,station_id) REFERENCES packing_stations(tenant_id,id),FOREIGN KEY(tenant_id,api_key_id) REFERENCES api_keys(tenant_id,id),
 CHECK(request_hash~'^[a-f0-9]{64}$' AND lease_token_hash~'^[a-f0-9]{64}$')
);
CREATE UNIQUE INDEX return_assistant_one_active ON return_assistant_sessions(tenant_id,return_id) WHERE state='active';
CREATE INDEX return_assistant_session_page ON return_assistant_sessions(tenant_id,return_id,created_at DESC,id DESC);
CREATE TABLE return_assistant_operations (
 id uuid PRIMARY KEY,tenant_id uuid NOT NULL,session_id uuid NOT NULL,actor_id uuid NOT NULL REFERENCES users,api_key_id uuid,client_key uuid NOT NULL,kind text NOT NULL,
 request_hash text NOT NULL,result jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,client_key),
 FOREIGN KEY(tenant_id,session_id) REFERENCES return_assistant_sessions(tenant_id,id),FOREIGN KEY(tenant_id,api_key_id) REFERENCES api_keys(tenant_id,id)
);
CREATE TABLE return_assistant_photos (
 id uuid PRIMARY KEY,tenant_id uuid NOT NULL,session_id uuid NOT NULL,return_id uuid NOT NULL,item_id uuid NOT NULL,part_id uuid,
 mime text NOT NULL CHECK(mime IN('image/png','image/jpeg')),byte_count integer NOT NULL CHECK(byte_count BETWEEN 1 AND 1048576),sha256 text NOT NULL CHECK(sha256~'^[a-f0-9]{64}$'),width integer NOT NULL CHECK(width BETWEEN 1 AND 8192),height integer NOT NULL CHECK(height BETWEEN 1 AND 8192),content_encrypted text NOT NULL,
 created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,session_id,return_id) REFERENCES return_assistant_sessions(tenant_id,id,return_id),FOREIGN KEY(tenant_id,return_id,item_id) REFERENCES return_items(tenant_id,return_id,item_id),CHECK(width::bigint*height<=16000000)
);
CREATE TABLE return_assistant_previews (
 id uuid PRIMARY KEY,tenant_id uuid NOT NULL,session_id uuid NOT NULL,return_id uuid NOT NULL,order_id uuid NOT NULL,actor_id uuid NOT NULL REFERENCES users,api_key_id uuid,client_key uuid NOT NULL,request_hash text NOT NULL,scope_hash text NOT NULL,private_scope_nonce uuid NOT NULL,payload jsonb NOT NULL,
 created_at timestamptz NOT NULL DEFAULT clock_timestamp(),expires_at timestamptz NOT NULL,UNIQUE(tenant_id,id),UNIQUE(tenant_id,id,session_id,return_id),UNIQUE(tenant_id,client_key),
 FOREIGN KEY(tenant_id,session_id,return_id) REFERENCES return_assistant_sessions(tenant_id,id,return_id),FOREIGN KEY(tenant_id,order_id,return_id) REFERENCES return_cases(tenant_id,order_id,id),FOREIGN KEY(tenant_id,api_key_id) REFERENCES api_keys(tenant_id,id),CHECK(scope_hash~'^[a-f0-9]{64}$' AND expires_at>created_at)
);
CREATE TABLE return_assistant_receipts (
 id uuid PRIMARY KEY,tenant_id uuid NOT NULL,preview_id uuid NOT NULL,session_id uuid NOT NULL,return_id uuid NOT NULL,order_id uuid NOT NULL,actor_id uuid NOT NULL REFERENCES users,api_key_id uuid,client_key uuid NOT NULL,request_hash text NOT NULL,scope_hash text NOT NULL,payload jsonb NOT NULL,result jsonb NOT NULL,
 created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,client_key),UNIQUE(tenant_id,preview_id),UNIQUE(tenant_id,return_id),UNIQUE(tenant_id,session_id),
 FOREIGN KEY(tenant_id,preview_id,session_id,return_id) REFERENCES return_assistant_previews(tenant_id,id,session_id,return_id),FOREIGN KEY(tenant_id,order_id,return_id) REFERENCES return_cases(tenant_id,order_id,id),FOREIGN KEY(tenant_id,api_key_id) REFERENCES api_keys(tenant_id,id)
);
CREATE TABLE return_assistant_admissions (
 tenant_id uuid NOT NULL,transaction_id xid8 NOT NULL,receipt_id uuid NOT NULL,preview_id uuid NOT NULL,session_id uuid NOT NULL,return_id uuid NOT NULL,actor_id uuid NOT NULL,api_key_id uuid,client_key uuid NOT NULL,request_hash text NOT NULL,payload jsonb NOT NULL,witnesses jsonb NOT NULL DEFAULT '[]',opened_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 PRIMARY KEY(tenant_id,transaction_id,receipt_id),FOREIGN KEY(tenant_id,receipt_id) REFERENCES return_assistant_receipts(tenant_id,id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(tenant_id,preview_id,session_id,return_id) REFERENCES return_assistant_previews(tenant_id,id,session_id,return_id)
);
DO $$DECLARE rel text;BEGIN FOREACH rel IN ARRAY ARRAY['return_assistant_sessions','return_assistant_operations','return_assistant_photos','return_assistant_previews','return_assistant_receipts','return_assistant_admissions'] LOOP
 EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',rel);EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',rel);
 EXECUTE format('CREATE POLICY tenant_scope ON %I TO dyna_app USING(tenant_id=nullif(current_setting(''app.tenant_id'',true),'''')::uuid)',rel);
 EXECUTE format('CREATE POLICY owner_scope ON %I TO %I USING(true) WITH CHECK(true)',rel,current_user);EXECUTE format('REVOKE ALL ON %I FROM PUBLIC,dyna_app',rel);
 IF rel NOT IN('return_assistant_sessions','return_assistant_previews','return_assistant_photos','return_assistant_admissions') THEN EXECUTE format('GRANT SELECT ON %I TO dyna_app',rel);END IF;
END LOOP;END $$;
GRANT SELECT(id,tenant_id,session_id,return_id,order_id,actor_id,api_key_id,client_key,request_hash,scope_hash,payload,created_at,expires_at) ON return_assistant_previews TO dyna_app;
GRANT SELECT(id,tenant_id,return_id,order_id,station_id,station,actor_id,api_key_id,client_key,request_hash,state,version,lease_generation,lease_expires_at,source,scanned,draft,created_at,updated_at) ON return_assistant_sessions TO dyna_app;
GRANT SELECT(id,tenant_id,session_id,return_id,item_id,part_id,mime,byte_count,sha256,width,height,created_at) ON return_assistant_photos TO dyna_app;
CREATE FUNCTION return_assistant_hash(v jsonb) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=public,pg_temp AS $$SELECT encode(sha256(convert_to(v::text,'UTF8')),'hex')$$;
CREATE FUNCTION return_assistant_token(v text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=public,pg_temp AS $$SELECT encode(sha256(convert_to(v,'UTF8')),'hex')$$;
CREATE FUNCTION return_assistant_installed() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$SELECT EXISTS(SELECT 1 FROM migrations WHERE name='139_return_assistant')$$;
CREATE FUNCTION return_assistant_access(uid uuid,kid uuid,writing boolean,pin boolean) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$DECLARE g jsonb;w boolean;BEGIN g:=order_parcel_access(uid,kid,writing,pin);w:=g->>'role' IN('admin','operator') AND g->'key_valid'='true'::jsonb AND(kid IS NULL OR EXISTS(SELECT 1 FROM api_keys k WHERE(k.tenant_id,k.id,k.user_id)=(nullif(current_setting('app.tenant_id',true),'')::uuid,kid,uid) AND k.scopes @> ARRAY['orders:read','orders:write']::text[]));RETURN g||jsonb_build_object('can_write',coalesce(w,false));END $$;
CREATE FUNCTION return_assistant_require(uid uuid,kid uuid,writing boolean,pin boolean) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$DECLARE g jsonb;BEGIN
 g:=return_assistant_access(uid,kid,writing,pin);IF g->'key_valid' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'Klucz asystenta jest nieaktualny' USING ERRCODE='23514';END IF;
 IF g->'allowed' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'Brak aktualnego uprawnienia do asystenta' USING ERRCODE='23514';END IF;RETURN g;
END $$;
CREATE FUNCTION return_assistant_lock() RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path=public,pg_temp AS $$SELECT pg_advisory_xact_lock(hashtextextended('return.assistant:'||current_setting('app.tenant_id'),0))$$;
CREATE FUNCTION return_assistant_budget() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$DECLARE t uuid:=nullif(current_setting('app.tenant_id',true),'')::uuid;n bigint;BEGIN
 IF(SELECT count(*) FROM return_assistant_sessions WHERE tenant_id=t)>2000 OR(SELECT count(*) FROM return_assistant_previews WHERE tenant_id=t)>2000 OR(SELECT count(*) FROM return_assistant_receipts WHERE tenant_id=t)>2000 OR(SELECT count(*) FROM return_assistant_operations WHERE tenant_id=t)>10000 OR EXISTS(SELECT 1 FROM return_assistant_photos WHERE tenant_id=t GROUP BY session_id HAVING count(*)>10) THEN RAISE EXCEPTION 'Limit historii asystenta' USING ERRCODE='23514';END IF;
 SELECT coalesce(sum(x.bytes),0) INTO n FROM(SELECT octet_length(to_jsonb(s)::text) bytes FROM return_assistant_sessions s WHERE tenant_id=t UNION ALL SELECT octet_length(to_jsonb(s)::text) FROM return_assistant_operations s WHERE tenant_id=t UNION ALL SELECT octet_length(to_jsonb(s)::text) FROM return_assistant_photos s WHERE tenant_id=t UNION ALL SELECT octet_length(to_jsonb(s)::text) FROM return_assistant_previews s WHERE tenant_id=t UNION ALL SELECT octet_length(to_jsonb(s)::text) FROM return_assistant_receipts s WHERE tenant_id=t UNION ALL SELECT octet_length(to_jsonb(s)::text) FROM return_assistant_admissions s WHERE tenant_id=t)x;
 IF n>67108864 THEN RAISE EXCEPTION 'Limit danych asystenta' USING ERRCODE='23514';END IF;
END $$;
CREATE FUNCTION return_assistant_source(rid uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE t uuid:=nullif(current_setting('app.tenant_id',true),'')::uuid;rc return_cases;od orders;line_rows jsonb;f jsonb;BEGIN
 SELECT * INTO rc FROM return_cases WHERE tenant_id=t AND id=rid;IF rc.id IS NULL THEN RAISE EXCEPTION 'Nie znaleziono RMA' USING ERRCODE='P0002';END IF;SELECT * INTO od FROM orders WHERE(tenant_id,id)=(t,rc.order_id);
 SELECT coalesce(jsonb_agg(jsonb_build_object('item_id',ri.item_id,'product_id',oi.product_id,'sku',ri.sku,'name',ri.name,'requested',ri.requested,'original_quantity',oi.quantity,'line_total',oi.line_total,'components',ri.components,'ordinal',rn,
 'codes',(SELECT coalesce(jsonb_agg(z.code ORDER BY z.code->>'kind',z.code->>'code'),'[]') FROM(SELECT jsonb_build_object('code',ri.sku,'kind','historical_sku') code UNION SELECT jsonb_build_object('code',p.sku,'kind','current_sku') FROM products p WHERE(p.tenant_id,p.id)=(t,oi.product_id) AND p.sku<>'' UNION SELECT jsonb_build_object('code',p.ean,'kind','current_ean') FROM products p WHERE(p.tenant_id,p.id)=(t,oi.product_id) AND coalesce(p.ean,'')<>'' UNION SELECT jsonb_build_object('code',al.sku,'kind','current_alias') FROM product_sku_aliases al WHERE(al.tenant_id,al.product_id)=(t,oi.product_id))z)) ORDER BY ri.item_id),'[]') INTO line_rows
 FROM(SELECT x.*,row_number() OVER(ORDER BY x.item_id)::int rn FROM return_items x WHERE(x.tenant_id,x.return_id)=(t,rid))ri JOIN order_items oi ON(oi.tenant_id,oi.order_id,oi.id)=(ri.tenant_id,ri.order_id,ri.item_id);
 IF jsonb_array_length(line_rows) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'RMA przekracza zakres pozycji asystenta' USING ERRCODE='23514';END IF;
 SELECT jsonb_build_object('return_case',to_jsonb(rc),'order',jsonb_build_object('id',od.id,'number',od.number,'version',od.version::text,'status',od.status,'warehouse_id',od.warehouse_id,'currency',od.currency,'items',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',oi.id,'product_id',oi.product_id,'sku',oi.sku,'name',oi.name,'quantity',oi.quantity,'line_total',oi.line_total,'vat',oi.vat,'components',oi.components) ORDER BY oi.id),'[]') FROM order_items oi WHERE(oi.tenant_id,oi.order_id)=(t,od.id)),'wms_lots_enabled',coalesce((SELECT enabled FROM wms_policies WHERE tenant_id=t),false)),
 'lines',line_rows,'stock',(SELECT coalesce(jsonb_agg(jsonb_build_object('product_id',p.product_id,'warehouse_id',rc.warehouse_id,'value',to_jsonb(s)) ORDER BY p.product_id),'[]') FROM(SELECT DISTINCT (c->>'product_id')::uuid product_id FROM jsonb_array_elements(line_rows) l CROSS JOIN LATERAL jsonb_array_elements(l->'components')c)p LEFT JOIN stock s ON(s.tenant_id,s.warehouse_id,s.product_id)=(t,rc.warehouse_id,p.product_id)),
 'stock_bins',(SELECT coalesce(jsonb_agg(to_jsonb(b) ORDER BY b.product_id,b.location COLLATE "C"),'[]') FROM stock_locations b WHERE(b.tenant_id,b.warehouse_id)=(t,rc.warehouse_id) AND b.product_id IN(SELECT (c->>'product_id')::uuid FROM jsonb_array_elements(line_rows) l CROSS JOIN LATERAL jsonb_array_elements(l->'components')c)),
 'wms_policy',(SELECT to_jsonb(w) FROM wms_policies w WHERE tenant_id=t),'issue_fragments',(SELECT coalesce(jsonb_agg(to_jsonb(z) ORDER BY z.id),'[]') FROM wms_issue_fragments z WHERE(z.tenant_id,z.order_id)=(t,od.id)),
 'parcel_claims',(SELECT coalesce(jsonb_agg(to_jsonb(cl) ORDER BY cl.ordinal),'[]') FROM order_parcel_return_claims cl WHERE(cl.tenant_id,cl.return_id)=(t,rid)),
 'positions',(SELECT coalesce(jsonb_agg(to_jsonb(z) ORDER BY z.product_id,z.layer_id,z.location COLLATE "C"),'[]') FROM wms_layer_positions z WHERE(z.tenant_id,z.warehouse_id)=(t,rc.warehouse_id) AND z.product_id IN(SELECT (c->>'product_id')::uuid FROM jsonb_array_elements(line_rows) l CROSS JOIN LATERAL jsonb_array_elements(l->'components')c)),
 'layers_hash',return_assistant_hash((SELECT coalesce(jsonb_agg(to_jsonb(z) ORDER BY z.id),'[]') FROM wms_cost_layers z WHERE z.tenant_id=t AND z.product_id IN(SELECT (c->>'product_id')::uuid FROM jsonb_array_elements(line_rows) l CROSS JOIN LATERAL jsonb_array_elements(l->'components')c))),
 'refund_basis',(SELECT coalesce(jsonb_agg(jsonb_build_object('item_id',bl->>'item_id','quantity',(bl->>'original_quantity')::int,'line_total',(bl->>'line_total')::bigint,'prior',coalesce((SELECT sum(pri.accepted) FROM return_items pri JOIN return_cases prc ON(prc.tenant_id,prc.id)=(pri.tenant_id,pri.return_id) WHERE(pri.tenant_id,pri.order_id,pri.item_id)=(t,od.id,(bl->>'item_id')::uuid) AND prc.id<>rid AND prc.state IN('refund_pending','closed')),0)) ORDER BY bl->>'item_id'),'[]') FROM jsonb_array_elements(line_rows)bl),
 'next_receipt_sequence',(SELECT coalesce(max(prc.receipt_sequence),0)+1 FROM return_cases prc WHERE(prc.tenant_id,prc.order_id)=(t,od.id) AND prc.id<>rid),
 'financial_hash',return_assistant_hash(jsonb_build_object('payments',(SELECT coalesce(jsonb_agg(to_jsonb(pe) ORDER BY pe.id),'[]') FROM payment_entries pe WHERE(pe.tenant_id,pe.order_id)=(t,od.id)),'documents',(SELECT coalesce(jsonb_agg(to_jsonb(d) ORDER BY d.id),'[]') FROM documents d WHERE(d.tenant_id,d.order_id)=(t,od.id))))) INTO f;
 IF octet_length(f::text)>4194304 THEN RAISE EXCEPTION 'Zakres RMA jest zbyt duży' USING ERRCODE='23514';END IF;RETURN f;
END $$;
CREATE FUNCTION return_assistant_session(sid uuid,uid uuid,kid uuid,b jsonb,allow_expired boolean DEFAULT false) RETURNS return_assistant_sessions LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$DECLARE t uuid:=nullif(current_setting('app.tenant_id',true),'')::uuid;s return_assistant_sessions;BEGIN
 PERFORM return_assistant_require(uid,kid,true,false);PERFORM return_assistant_lock();SELECT * INTO s FROM return_assistant_sessions WHERE(tenant_id,id)=(t,sid) FOR UPDATE;
 IF s.id IS NULL THEN RAISE EXCEPTION 'Nie znaleziono sesji' USING ERRCODE='P0002';END IF;
 IF s.state<>'active' OR(s.actor_id,s.api_key_id) IS DISTINCT FROM(uid,kid) OR return_assistant_token(b->>'lease_token') IS DISTINCT FROM s.lease_token_hash OR(NOT allow_expired AND s.lease_expires_at<=clock_timestamp()) OR s.version::text IS DISTINCT FROM b->>'version' THEN RAISE EXCEPTION 'Sesja wymaga świeżego własnego lease i wersji' USING ERRCODE='23514';END IF;RETURN s;
END $$;
CREATE FUNCTION return_assistant_replay(sid uuid,op text,b jsonb,uid uuid,kid uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$DECLARE t uuid:=nullif(current_setting('app.tenant_id',true),'')::uuid;r return_assistant_operations;h text;BEGIN
 PERFORM return_assistant_require(uid,kid,true,false);PERFORM return_assistant_lock();h:=return_assistant_hash(jsonb_build_object('tenant_id',t,'session_id',sid,'kind',op,'request',b,'actor_id',uid,'api_key_id',kid));SELECT * INTO r FROM return_assistant_operations WHERE tenant_id=t AND client_key=(b->>'client_key')::uuid;
 IF r.id IS NOT NULL THEN IF(r.session_id,r.kind,r.actor_id,r.api_key_id,r.request_hash) IS DISTINCT FROM(sid,op,uid,kid,h) THEN RAISE EXCEPTION 'Klucz operacji ma inny zakres' USING ERRCODE='23514';END IF;RETURN r.id;END IF;RETURN NULL;
END $$;
CREATE FUNCTION return_assistant_start(sid uuid,b jsonb,uid uuid,kid uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$DECLARE t uuid:=nullif(current_setting('app.tenant_id',true),'')::uuid;s return_assistant_sessions;rc return_cases;st packing_stations;h text;f jsonb;BEGIN
 PERFORM return_assistant_require(uid,kid,true,false);PERFORM return_assistant_lock();h:=return_assistant_hash(jsonb_build_object('tenant_id',t,'kind','start','request',b,'actor_id',uid,'api_key_id',kid));SELECT * INTO s FROM return_assistant_sessions WHERE tenant_id=t AND client_key=(b->>'client_key')::uuid;
 IF s.id IS NOT NULL THEN IF(s.actor_id,s.api_key_id,s.request_hash) IS DISTINCT FROM(uid,kid,h) THEN RAISE EXCEPTION 'Klucz sesji ma inny zakres' USING ERRCODE='23514';END IF;RETURN s.id;END IF;
 SELECT * INTO rc FROM return_cases WHERE tenant_id=t AND number=b->>'return_number';IF rc.id IS NULL THEN RAISE EXCEPTION 'Nie znaleziono numeru RMA' USING ERRCODE='P0002';END IF;
 PERFORM 1 FROM orders WHERE(tenant_id,id)=(t,rc.order_id) FOR UPDATE;SELECT * INTO rc FROM return_cases WHERE(tenant_id,id)=(t,rc.id) FOR UPDATE;
 IF rc.state<>'requested' OR rc.receipt IS NOT NULL OR rc.legacy OR coalesce(to_jsonb(rc)->>'remedy','refund')<>'refund' THEN RAISE EXCEPTION 'RMA wymaga innego procesu przyjęcia' USING ERRCODE='23514';END IF;
 IF EXISTS(SELECT 1 FROM b2b_dropship_return_cases WHERE(tenant_id,return_id)=(t,rc.id)) OR EXISTS(SELECT 1 FROM b2b_dropship_return_supplier_cases WHERE(tenant_id,return_id)=(t,rc.id)) THEN RAISE EXCEPTION 'Skoordynowany zwrot obsłuż przez proces B2B' USING ERRCODE='23514';END IF;
 SELECT * INTO st FROM packing_stations WHERE tenant_id=t AND id=(b->>'station_id')::uuid FOR SHARE;
 IF st.id IS NULL OR NOT st.enabled OR st.version::text IS DISTINCT FROM b->>'station_version' THEN RAISE EXCEPTION 'Stanowisko zmieniło wersję lub jest wyłączone' USING ERRCODE='23514';END IF;
 IF b2b_return_local_external(rc.id) AND NOT EXISTS(SELECT 1 FROM b2b_return_local_origins lo WHERE(lo.tenant_id,lo.return_id)=(t,rc.id)) THEN RAISE EXCEPTION 'Najpierw wybierz lokalne pochodzenie RMA' USING ERRCODE='23514';END IF;
 f:=return_assistant_source(rc.id);INSERT INTO return_assistant_sessions(id,tenant_id,return_id,order_id,station_id,station,actor_id,api_key_id,client_key,request_hash,lease_token_hash,lease_expires_at,source) VALUES(sid,t,rc.id,rc.order_id,st.id,jsonb_build_object('id',st.id,'version',st.version::text,'code',st.code,'label',st.label,'enabled',st.enabled),uid,kid,(b->>'client_key')::uuid,h,return_assistant_token(b->>'lease_token'),clock_timestamp()+interval '15 minutes',f);
 UPDATE return_assistant_sessions SET draft=draft||jsonb_build_object('origin_id',lo.id) FROM b2b_return_local_origins lo WHERE(return_assistant_sessions.tenant_id,return_assistant_sessions.id)=(t,sid) AND(lo.tenant_id,lo.return_id)=(t,rc.id);
 PERFORM return_assistant_require(uid,kid,true,false);PERFORM return_assistant_budget();RETURN sid;
END $$;
CREATE FUNCTION return_assistant_decisions(s return_assistant_sessions,complete boolean) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$DECLARE l jsonb;p jsonb;out_rows jsonb:='[]';total_qty bigint;accepted_qty bigint;restocked_qty bigint;seen_qty bigint;BEGIN
 IF jsonb_typeof(s.draft->'parts') IS DISTINCT FROM 'array' OR jsonb_array_length(s.draft->'parts')>200 OR EXISTS(SELECT 1 FROM jsonb_array_elements(s.draft->'parts')x GROUP BY x->>'part_id' HAVING count(*)>1) THEN RAISE EXCEPTION 'Nieprawidłowe części kontroli' USING ERRCODE='23514';END IF;
 FOR p IN SELECT value FROM jsonb_array_elements(s.draft->'parts') LOOP
  IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(s.source->'lines')x WHERE x->>'item_id'=p->>'item_id') OR coalesce(p->>'status','') NOT IN('sale','hold','reject') OR jsonb_typeof(p->'quantity') IS DISTINCT FROM 'number' OR coalesce(p->>'quantity','')!~'^[1-9][0-9]{0,5}$' OR(p->>'quantity')::int>100000 OR coalesce(p->>'part_id','')!~'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$' THEN RAISE EXCEPTION 'Nieprawidłowa część kontroli' USING ERRCODE='23514';END IF;
 END LOOP;
 FOR l IN SELECT value FROM jsonb_array_elements(s.source->'lines') LOOP
  SELECT coalesce(sum((x->>'quantity')::int),0),coalesce(sum((x->>'quantity')::int) FILTER(WHERE x->>'status'<>'reject'),0),coalesce(sum((x->>'quantity')::int) FILTER(WHERE x->>'status'='sale'),0) INTO total_qty,accepted_qty,restocked_qty FROM jsonb_array_elements(s.draft->'parts')x WHERE x->>'item_id'=l->>'item_id';
  SELECT coalesce(sum((x->>'quantity')::int),0) INTO seen_qty FROM jsonb_array_elements(s.scanned)x WHERE x->>'item_id'=l->>'item_id';
  IF total_qty>(l->>'requested')::int OR(complete AND total_qty<>(l->>'requested')::int) OR accepted_qty>seen_qty THEN RAISE EXCEPTION 'Ilości wymagają pełnej zgodnej kontroli' USING ERRCODE='23514';END IF;
  out_rows:=out_rows||jsonb_build_array(jsonb_build_object('item_id',l->>'item_id','accepted',accepted_qty,'restocked',restocked_qty));
 END LOOP;RETURN out_rows;
END $$;
CREATE FUNCTION return_assistant_step(sid uuid,op text,b jsonb,uid uuid,kid uuid,photo jsonb DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$DECLARE t uuid:=nullif(current_setting('app.tenant_id',true),'')::uuid;s return_assistant_sessions;prior uuid;operation_id uuid:=gen_random_uuid();selected uuid;matches jsonb;seen_qty integer;photo_id uuid;g jsonb;BEGIN
 prior:=return_assistant_replay(sid,op,b,uid,kid);IF prior IS NOT NULL THEN RETURN prior;END IF;
 IF op='takeover' THEN
  g:=return_assistant_require(uid,kid,true,false);IF g->>'role'<>'admin' THEN RAISE EXCEPTION 'Przejęcie sesji wymaga administratora' USING ERRCODE='23514';END IF;
  SELECT * INTO s FROM return_assistant_sessions WHERE(tenant_id,id)=(t,sid) FOR UPDATE;IF s.id IS NULL OR s.state<>'active' OR s.version::text IS DISTINCT FROM b->>'version' OR s.lease_expires_at>clock_timestamp() THEN RAISE EXCEPTION 'Można przejąć tylko wygasłą sesję' USING ERRCODE='23514';END IF;
  UPDATE return_assistant_sessions SET actor_id=uid,api_key_id=kid,lease_token_hash=return_assistant_token(b->>'lease_token'),lease_generation=lease_generation+1 WHERE(tenant_id,id)=(t,sid);
 ELSE s:=return_assistant_session(sid,uid,kid,b,op='renew');END IF;
 IF op='scan' THEN
  SELECT coalesce(jsonb_agg(x->>'item_id' ORDER BY x->>'item_id'),'[]') INTO matches FROM jsonb_array_elements(s.source->'lines')x WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(x->'codes')c WHERE c->>'code'=b->>'code');
  IF jsonb_array_length(matches)=0 THEN RAISE EXCEPTION 'Kod nie należy do pozycji tego RMA' USING ERRCODE='23514';END IF;
  IF b ? 'item_id' THEN selected:=(b->>'item_id')::uuid;IF NOT(matches @> jsonb_build_array(selected::text)) THEN RAISE EXCEPTION 'Wybrana pozycja nie odpowiada kodowi' USING ERRCODE='23514';END IF;
  ELSE IF jsonb_array_length(matches)<>1 THEN RAISE EXCEPTION 'Kod jest niejednoznaczny; wybierz pozycję RMA' USING ERRCODE='23514';END IF;selected:=(matches->>0)::uuid;END IF;
  SELECT coalesce(sum((x->>'quantity')::int),0) INTO seen_qty FROM jsonb_array_elements(s.scanned)x WHERE x->>'item_id'=selected::text;
  IF seen_qty >= (SELECT (x->>'requested')::int FROM jsonb_array_elements(s.source->'lines')x WHERE x->>'item_id'=selected::text) THEN RAISE EXCEPTION 'Zeskanowano już całą zgłoszoną ilość' USING ERRCODE='23514';END IF;
  s.scanned:=coalesce((SELECT jsonb_agg(x ORDER BY x->>'item_id') FROM jsonb_array_elements(s.scanned)x WHERE x->>'item_id'<>selected::text),'[]')||jsonb_build_array(jsonb_build_object('item_id',selected,'quantity',seen_qty+1));
 ELSIF op='draft' THEN
  s.draft:=b-ARRAY['client_key','version','lease_token'];PERFORM return_assistant_decisions(s,false);
  IF char_length(coalesce(s.draft->>'note','')) NOT BETWEEN 3 AND 2000 OR jsonb_typeof(s.draft->'shipping_refund') IS DISTINCT FROM 'number' OR coalesce(s.draft->>'shipping_refund','')!~'^[0-9]{1,7}$' OR(s.draft->>'shipping_refund')::int NOT BETWEEN 0 AND 1000000 OR EXISTS(SELECT 1 FROM return_assistant_photos ph WHERE(ph.tenant_id,ph.session_id)=(t,sid) AND ph.part_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(s.draft->'parts')pt WHERE(pt->>'part_id',pt->>'item_id')=(ph.part_id::text,ph.item_id::text))) THEN RAISE EXCEPTION 'Szkic wymaga poprawnej notatki i trwałych części zdjęć' USING ERRCODE='23514';END IF;
 ELSIF op='photo' THEN
  IF photo IS NULL OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(s.source->'lines')x WHERE x->>'item_id'=b->>'item_id') OR((b ? 'part_id') AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(s.draft->'parts')x WHERE(x->>'part_id',x->>'item_id')=(b->>'part_id',b->>'item_id'))) OR(SELECT count(*) FROM return_assistant_photos WHERE(tenant_id,session_id)=(t,sid))>=10 THEN RAISE EXCEPTION 'Zdjęcie wymaga własnej pozycji lub części i wolnego limitu' USING ERRCODE='23514';END IF;
  photo_id:=gen_random_uuid();INSERT INTO return_assistant_photos(id,tenant_id,session_id,return_id,item_id,part_id,mime,byte_count,sha256,width,height,content_encrypted) VALUES(photo_id,t,sid,s.return_id,(b->>'item_id')::uuid,(b->>'part_id')::uuid,photo->>'mime',(photo->>'byte_count')::int,photo->>'sha256',(photo->>'width')::int,(photo->>'height')::int,photo->>'content_encrypted');
 ELSIF op='cancel' THEN s.state:='cancelled';
 ELSIF op NOT IN('renew','takeover') THEN RAISE EXCEPTION 'Nieznana operacja asystenta' USING ERRCODE='23514';END IF;
 UPDATE return_assistant_sessions SET scanned=s.scanned,draft=s.draft,state=s.state,version=version+1,updated_at=clock_timestamp(),lease_expires_at=clock_timestamp()+interval '15 minutes' WHERE(tenant_id,id)=(t,sid);
 INSERT INTO return_assistant_operations(id,tenant_id,session_id,actor_id,api_key_id,client_key,kind,request_hash,result) VALUES(operation_id,t,sid,uid,kid,(b->>'client_key')::uuid,op,return_assistant_hash(jsonb_build_object('tenant_id',t,'session_id',sid,'kind',op,'request',b,'actor_id',uid,'api_key_id',kid)),jsonb_build_object('session_id',sid,'version',(s.version+1)::text,'photo_id',photo_id));
 PERFORM return_assistant_require(uid,kid,true,false);PERFORM return_assistant_budget();RETURN operation_id;
END $$;
CREATE FUNCTION return_assistant_frame(sid uuid,b jsonb,uid uuid,kid uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE t uuid:=nullif(current_setting('app.tenant_id',true),'')::uuid;s return_assistant_sessions;st packing_stations;f jsonb;decisions jsonb;core jsonb;photos jsonb;action_kind text;accepted_qty bigint;restocked_qty bigint;scanned_qty bigint;requested_qty bigint;credit bigint;li record;prev_qty bigint;BEGIN
 s:=return_assistant_session(sid,uid,kid,b);PERFORM 1 FROM orders WHERE(tenant_id,id)=(t,s.order_id) FOR UPDATE;PERFORM 1 FROM return_cases WHERE(tenant_id,id)=(t,s.return_id) FOR UPDATE;
 PERFORM 1 FROM stock sk WHERE(sk.tenant_id,sk.warehouse_id)=(t,(s.source->'return_case'->>'warehouse_id')::uuid) AND sk.product_id IN(SELECT (c->>'product_id')::uuid FROM jsonb_array_elements(s.source->'lines')l CROSS JOIN LATERAL jsonb_array_elements(l->'components')c) ORDER BY sk.product_id FOR UPDATE;
 f:=return_assistant_source(s.return_id);
 IF f->'return_case'->>'state'<>'requested' OR f->'return_case'->'receipt' IS DISTINCT FROM 'null'::jsonb OR f->'return_case'->>'version' IS DISTINCT FROM s.source->'return_case'->>'version' OR (SELECT jsonb_agg(x-ARRAY['codes'] ORDER BY x->>'item_id') FROM jsonb_array_elements(f->'lines')x) IS DISTINCT FROM(SELECT jsonb_agg(x-ARRAY['codes'] ORDER BY x->>'item_id') FROM jsonb_array_elements(s.source->'lines')x) THEN RAISE EXCEPTION 'RMA lub historyczne pozycje zmieniły zakres' USING ERRCODE='23514';END IF;
 SELECT * INTO st FROM packing_stations WHERE(tenant_id,id)=(t,s.station_id) FOR SHARE;
 IF st.id IS NULL OR NOT st.enabled OR st.version::text IS DISTINCT FROM s.station->>'version' THEN RAISE EXCEPTION 'Stanowisko zmieniło wersję lub jest wyłączone' USING ERRCODE='23514';END IF;
 IF char_length(coalesce(s.draft->>'note','')) NOT BETWEEN 3 AND 2000 THEN RAISE EXCEPTION 'Podgląd wymaga notatki kontroli' USING ERRCODE='23514';END IF;
 decisions:=return_assistant_decisions(s,true);
 SELECT coalesce(sum((x->>'accepted')::int),0),coalesce(sum((x->>'restocked')::int),0) INTO accepted_qty,restocked_qty FROM jsonb_array_elements(decisions)x;
 SELECT coalesce(sum((x->>'quantity')::int),0) INTO scanned_qty FROM jsonb_array_elements(s.scanned)x;
 SELECT sum((x->>'requested')::int) INTO requested_qty FROM jsonb_array_elements(s.source->'lines')x;
 IF (s.draft->>'shipping_refund')::int>(f->'return_case'->>'requested_shipping')::int THEN RAISE EXCEPTION 'Zwrot dostawy przekracza zgłoszenie' USING ERRCODE='23514';END IF;
 action_kind:=CASE WHEN accepted_qty=0 THEN 'reject' ELSE 'receive' END;
 IF action_kind='reject' THEN
  IF(s.draft->>'shipping_refund')::int<>0 THEN RAISE EXCEPTION 'Całkowite odrzucenie nie zwraca dostawy' USING ERRCODE='23514';END IF;
  core:=jsonb_build_object('version',(f->'return_case'->>'version')::bigint,'decision','reject','note',s.draft->>'note');credit:=0;
 ELSE
  core:=jsonb_build_object('version',(f->'return_case'->>'version')::bigint,'items',decisions,'note',s.draft->>'note','shipping_refund',(s.draft->>'shipping_refund')::int);
  IF s.draft ? 'origin_id' THEN core:=core||jsonb_build_object('origin_id',s.draft->'origin_id');END IF;
  IF s.draft ? 'wms_lots' THEN core:=core||jsonb_build_object('wms_lots',s.draft->'wms_lots');END IF;
  IF f->'order'->'wms_lots_enabled'='true'::jsonb AND restocked_qty>0 AND jsonb_array_length(f->'issue_fragments')=0 THEN RAISE EXCEPTION 'Historyczny restock bez fragmentów WMS obsłuż dotychczasowym procesem' USING ERRCODE='23514';END IF;
  IF f->'order'->'wms_lots_enabled'='true'::jsonb AND restocked_qty>0 AND NOT(core ? 'wms_lots') THEN RAISE EXCEPTION 'WMS wymaga jawnego wyboru fragmentów wydania' USING ERRCODE='23514';END IF;
  credit:=(s.draft->>'shipping_refund')::int;
  FOR li IN SELECT l.item_id,l.accepted,l.quantity,l.line_total FROM(SELECT (x->>'item_id')::uuid item_id,(x->>'accepted')::int accepted FROM jsonb_array_elements(decisions)x)d JOIN order_items l0 ON(l0.tenant_id,l0.order_id,l0.id)=(t,s.order_id,d.item_id) CROSS JOIN LATERAL(SELECT d.item_id,d.accepted,l0.quantity,l0.line_total)l LOOP
   SELECT coalesce(sum(ri.accepted),0) INTO prev_qty FROM return_items ri JOIN return_cases rc ON(rc.tenant_id,rc.id)=(ri.tenant_id,ri.return_id) WHERE(ri.tenant_id,ri.order_id,ri.item_id)=(t,s.order_id,li.item_id) AND rc.state IN('refund_pending','closed');
   IF prev_qty+li.accepted>li.quantity THEN RAISE EXCEPTION 'Ilość przyjęto już w innej sprawie' USING ERRCODE='23514';END IF;
   credit:=credit+floor(li.line_total::numeric*(prev_qty+li.accepted)/li.quantity)::bigint-floor(li.line_total::numeric*prev_qty/li.quantity)::bigint;
  END LOOP;
 END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',ph.id,'item_id',ph.item_id,'part_id',ph.part_id,'mime',ph.mime,'byte_count',ph.byte_count,'sha256',ph.sha256,'width',ph.width,'height',ph.height,'created_at',ph.created_at) ORDER BY ph.id),'[]') INTO photos FROM return_assistant_photos ph WHERE(ph.tenant_id,ph.session_id)=(t,sid);
 RETURN jsonb_build_object('action',action_kind,'receive_input',core,'snapshot',jsonb_build_object('session',jsonb_build_object('id',s.id,'version',s.version::text,'station_id',s.station_id,'station',s.station),'return_case',f->'return_case','order',f->'order','lines',s.source->'lines','scanned',s.scanned,'parts',s.draft->'parts','photos',photos,'source',f-ARRAY['return_case','order','lines']),
 'summary',jsonb_build_object('requested',requested_qty,'scanned',scanned_qty,'accepted',accepted_qty,'restocked',restocked_qty,'held',accepted_qty-restocked_qty,'rejected',requested_qty-accepted_qty,'photo_count',jsonb_array_length(photos),'refund_minor',credit,'shipping_refund',(s.draft->>'shipping_refund')::int,'currency',f->'order'->>'currency'));
END $$;
CREATE FUNCTION return_assistant_preview(pid uuid,sid uuid,b jsonb,uid uuid,kid uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$DECLARE t uuid:=nullif(current_setting('app.tenant_id',true),'')::uuid;p return_assistant_previews;s return_assistant_sessions;h text;f jsonb;nonce uuid:=gen_random_uuid();BEGIN
 PERFORM return_assistant_require(uid,kid,true,false);PERFORM return_assistant_lock();h:=return_assistant_hash(jsonb_build_object('tenant_id',t,'session_id',sid,'kind','preview','request',b,'actor_id',uid,'api_key_id',kid));SELECT * INTO p FROM return_assistant_previews WHERE tenant_id=t AND client_key=(b->>'client_key')::uuid;
 IF p.id IS NOT NULL THEN IF(p.session_id,p.actor_id,p.api_key_id,p.request_hash) IS DISTINCT FROM(sid,uid,kid,h) THEN RAISE EXCEPTION 'Klucz podglądu ma inny zakres' USING ERRCODE='23514';END IF;RETURN p.id;END IF;
 f:=return_assistant_frame(sid,b,uid,kid);SELECT * INTO s FROM return_assistant_sessions WHERE(tenant_id,id)=(t,sid);
 IF octet_length(f::text)>4194304 THEN RAISE EXCEPTION 'Podgląd asystenta jest zbyt duży' USING ERRCODE='23514';END IF;
 INSERT INTO return_assistant_previews(id,tenant_id,session_id,return_id,order_id,actor_id,api_key_id,client_key,request_hash,scope_hash,private_scope_nonce,payload,expires_at) VALUES(pid,t,sid,s.return_id,s.order_id,uid,kid,(b->>'client_key')::uuid,h,return_assistant_hash(f||jsonb_build_object('private_scope_nonce',nonce)),nonce,f,clock_timestamp()+interval '15 minutes');PERFORM return_assistant_require(uid,kid,true,false);PERFORM return_assistant_budget();RETURN pid;
END $$;
CREATE FUNCTION return_assistant_prepare(pid uuid,eid uuid,b jsonb,uid uuid,kid uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$DECLARE t uuid:=nullif(current_setting('app.tenant_id',true),'')::uuid;p return_assistant_previews;r return_assistant_receipts;s return_assistant_sessions;h text;f jsonb;BEGIN
 PERFORM return_assistant_require(uid,kid,true,false);PERFORM return_assistant_lock();SELECT * INTO p FROM return_assistant_previews WHERE(tenant_id,id)=(t,pid);IF p.id IS NULL THEN RAISE EXCEPTION 'Nie znaleziono podglądu' USING ERRCODE='P0002';END IF;
 h:=return_assistant_hash(jsonb_build_object('tenant_id',t,'preview_id',pid,'kind','receive','request',b,'actor_id',uid,'api_key_id',kid));SELECT * INTO r FROM return_assistant_receipts WHERE tenant_id=t AND client_key=(b->>'client_key')::uuid;
 IF r.id IS NOT NULL THEN IF(r.preview_id,r.actor_id,r.api_key_id,r.request_hash) IS DISTINCT FROM(pid,uid,kid,h) THEN RAISE EXCEPTION 'Klucz zgody ma inny zakres' USING ERRCODE='23514';END IF;RETURN r.id;END IF;
 IF(p.actor_id,p.api_key_id) IS DISTINCT FROM(uid,kid) OR p.expires_at<=clock_timestamp() OR b->'confirmed' IS DISTINCT FROM 'true'::jsonb OR b->>'scope_hash' IS DISTINCT FROM p.scope_hash THEN RAISE EXCEPTION 'Zgoda wymaga świeżego własnego podglądu' USING ERRCODE='23514';END IF;
 f:=return_assistant_frame(p.session_id,jsonb_build_object('version',p.payload->'snapshot'->'session'->>'version','lease_token',b->>'lease_token'),uid,kid);
 IF f IS DISTINCT FROM p.payload THEN RAISE EXCEPTION 'Zakres kontroli zmienił się; odczytaj nowy podgląd' USING ERRCODE='23514';END IF;
 INSERT INTO return_assistant_admissions(tenant_id,transaction_id,receipt_id,preview_id,session_id,return_id,actor_id,api_key_id,client_key,request_hash,payload) VALUES(t,pg_current_xact_id(),eid,p.id,p.session_id,p.return_id,uid,kid,(b->>'client_key')::uuid,h,p.payload);RETURN eid;
END $$;
CREATE FUNCTION return_assistant_finish(eid uuid,uid uuid,kid uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$DECLARE t uuid:=nullif(current_setting('app.tenant_id',true),'')::uuid;a return_assistant_admissions;p return_assistant_previews;rc return_cases;BEGIN
 PERFORM return_assistant_require(uid,kid,true,false);SELECT * INTO a FROM return_assistant_admissions WHERE(tenant_id,transaction_id,receipt_id)=(t,pg_current_xact_id(),eid);
 IF a.receipt_id IS NULL OR(a.actor_id,a.api_key_id) IS DISTINCT FROM(uid,kid) THEN RAISE EXCEPTION 'Brak bieżącej zgody asystenta' USING ERRCODE='23514';END IF;
 SELECT * INTO p FROM return_assistant_previews WHERE(tenant_id,id)=(t,a.preview_id);SELECT * INTO rc FROM return_cases WHERE(tenant_id,id)=(t,a.return_id);
 IF rc.version IS DISTINCT FROM (p.payload->'receive_input'->>'version')::bigint+1 OR (p.payload->>'action'='receive' AND(rc.state<>'refund_pending' OR rc.receipt IS DISTINCT FROM p.payload->'receive_input' OR (rc.received_at IS NULL OR rc.received_at<transaction_timestamp()))) OR(p.payload->>'action'='reject' AND(rc.state<>'rejected' OR rc.receipt IS NOT NULL OR rc.refund_amount<>0)) THEN RAISE EXCEPTION 'Brak rzeczywistego przyjęcia lub odrzucenia core' USING ERRCODE='23514';END IF;
 UPDATE return_assistant_sessions SET state='completed',version=version+1,updated_at=clock_timestamp() WHERE(tenant_id,id)=(t,p.session_id);
 INSERT INTO return_assistant_receipts(id,tenant_id,preview_id,session_id,return_id,order_id,actor_id,api_key_id,client_key,request_hash,scope_hash,payload,result) VALUES(eid,t,p.id,p.session_id,p.return_id,p.order_id,uid,kid,a.client_key,a.request_hash,p.scope_hash,p.payload,jsonb_build_object('state',rc.state,'version',rc.version::text,'refund_amount',rc.refund_amount,'refunded_shipping',rc.refunded_shipping,'received_at',rc.received_at,'receipt',rc.receipt,'decision_note',rc.decision_note));
 PERFORM return_assistant_budget();RETURN eid;
END $$;
CREATE FUNCTION return_assistant_photo_content(pid uuid,uid uuid,kid uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$DECLARE t uuid:=nullif(current_setting('app.tenant_id',true),'')::uuid;p return_assistant_photos;BEGIN
 PERFORM return_assistant_require(uid,kid,false,false);SELECT * INTO p FROM return_assistant_photos WHERE(tenant_id,id)=(t,pid);IF p.id IS NULL THEN RAISE EXCEPTION 'Nie znaleziono zdjęcia' USING ERRCODE='P0002';END IF;RETURN jsonb_build_object('id',p.id,'mime',p.mime,'byte_count',p.byte_count,'sha256',p.sha256,'width',p.width,'height',p.height,'content_encrypted',p.content_encrypted);
END $$;
CREATE FUNCTION return_assistant_immutable() RETURNS trigger LANGUAGE plpgsql SET search_path=public,pg_temp AS $$BEGIN IF TG_TABLE_NAME='return_assistant_admissions' AND TG_OP='UPDATE' AND pg_trigger_depth()>=2 THEN IF(to_jsonb(NEW)-'witnesses') IS NOT DISTINCT FROM(to_jsonb(OLD)-'witnesses') AND jsonb_typeof(to_jsonb(NEW)->'witnesses')='array' AND jsonb_array_length(to_jsonb(NEW)->'witnesses')<=10000 THEN RETURN NEW;END IF;END IF;RAISE EXCEPTION 'Historia asystenta jest niezmienna' USING ERRCODE='23514';END $$;
CREATE FUNCTION return_assistant_complete() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE t uuid:=NEW.tenant_id;eid uuid;a return_assistant_admissions;r return_assistant_receipts;p return_assistant_previews;rc return_cases;cur jsonb;d jsonb;ri return_items;phys record;before_qty integer;after_qty integer;basis jsonb;expected_credit bigint;BEGIN
 IF TG_TABLE_NAME='return_assistant_admissions' THEN eid:=NEW.receipt_id;ELSE eid:=NEW.id;END IF;
 SELECT * INTO r FROM return_assistant_receipts WHERE(tenant_id,id)=(t,eid);SELECT * INTO a FROM return_assistant_admissions WHERE(tenant_id,transaction_id,receipt_id)=(t,pg_current_xact_id(),eid);
 IF r.id IS NULL OR a.receipt_id IS NULL OR(r.preview_id,r.session_id,r.return_id,r.actor_id,r.api_key_id,r.client_key,r.request_hash,r.payload) IS DISTINCT FROM(a.preview_id,a.session_id,a.return_id,a.actor_id,a.api_key_id,a.client_key,a.request_hash,a.payload) THEN RAISE EXCEPTION 'Przyjęcie wymaga dokładnej świeżej zgody asystenta' USING ERRCODE='23514';END IF;
 SELECT * INTO p FROM return_assistant_previews WHERE(tenant_id,id)=(t,r.preview_id);SELECT * INTO rc FROM return_cases WHERE(tenant_id,id)=(t,r.return_id);cur:=return_assistant_source(r.return_id);
 IF r.payload IS DISTINCT FROM p.payload OR r.scope_hash IS DISTINCT FROM p.scope_hash OR rc.version IS DISTINCT FROM(r.payload->'receive_input'->>'version')::bigint+1 OR NOT EXISTS(SELECT 1 FROM return_assistant_sessions ss WHERE(ss.tenant_id,ss.id)=(t,r.session_id) AND ss.state='completed' AND ss.version=(p.payload->'snapshot'->'session'->>'version')::bigint+1) OR cur->>'financial_hash' IS DISTINCT FROM p.payload->'snapshot'->'source'->>'financial_hash' THEN RAISE EXCEPTION 'Receipt asystenta ma niespójny zakres' USING ERRCODE='23514';END IF;
 IF r.payload->>'action'='receive' THEN
  IF rc.state<>'refund_pending' OR rc.receipt IS DISTINCT FROM r.payload->'receive_input' OR rc.refund_amount IS DISTINCT FROM(r.payload->'summary'->>'refund_minor')::int OR rc.refunded_shipping IS DISTINCT FROM(r.payload->'summary'->>'shipping_refund')::int OR rc.decision_note IS DISTINCT FROM r.payload->'receive_input'->>'note' OR rc.receipt_sequence IS DISTINCT FROM(r.payload->'snapshot'->'source'->>'next_receipt_sequence')::int OR cur->'refund_basis' IS DISTINCT FROM r.payload->'snapshot'->'source'->'refund_basis' OR (rc.received_at IS NULL OR rc.received_at<transaction_timestamp()) THEN RAISE EXCEPTION 'Receipt nie odpowiada przyjęciu RMA' USING ERRCODE='23514';END IF;
  FOR d IN SELECT value FROM jsonb_array_elements(r.payload->'receive_input'->'items') LOOP
   SELECT * INTO ri FROM return_items WHERE(tenant_id,return_id,item_id)=(t,r.return_id,(d->>'item_id')::uuid);
   SELECT x INTO basis FROM jsonb_array_elements(r.payload->'snapshot'->'source'->'refund_basis')x WHERE x->>'item_id'=d->>'item_id';
   expected_credit:=floor((basis->>'line_total')::numeric*((basis->>'prior')::bigint+(d->>'accepted')::int)/(basis->>'quantity')::int)::bigint-floor((basis->>'line_total')::numeric*(basis->>'prior')::bigint/(basis->>'quantity')::int)::bigint;
   IF basis IS NULL OR ri.item_id IS NULL OR(ri.accepted,ri.restocked,ri.refund_amount) IS DISTINCT FROM((d->>'accepted')::int,(d->>'restocked')::int,expected_credit) THEN RAISE EXCEPTION 'Receipt ma inne ilości pozycji' USING ERRCODE='23514';END IF;
  END LOOP;
 ELSE IF rc.state<>'rejected' OR rc.receipt IS NOT NULL OR rc.refund_amount<>0 OR rc.refunded_shipping<>0 OR rc.decision_note IS DISTINCT FROM r.payload->'receive_input'->>'note' THEN RAISE EXCEPTION 'Receipt nie odpowiada odrzuceniu RMA' USING ERRCODE='23514';END IF;END IF;
 FOR phys IN SELECT (c->>'product_id')::uuid product_id,coalesce(sum((c->>'quantity')::bigint*coalesce((de->>'restocked')::int,0)),0) qty FROM jsonb_array_elements(p.payload->'snapshot'->'lines')li CROSS JOIN LATERAL jsonb_array_elements(li->'components')c LEFT JOIN LATERAL(SELECT value de FROM jsonb_array_elements(CASE WHEN r.payload->>'action'='receive' THEN r.payload->'receive_input'->'items' ELSE '[]'::jsonb END)x WHERE x->>'item_id'=li->>'item_id')z ON true GROUP BY c->>'product_id' LOOP
  SELECT coalesce((x->'value'->>'on_hand')::int,0) INTO before_qty FROM jsonb_array_elements(p.payload->'snapshot'->'source'->'stock')x WHERE x->>'product_id'=phys.product_id::text;
  SELECT coalesce((x->'value'->>'on_hand')::int,0) INTO after_qty FROM jsonb_array_elements(cur->'stock')x WHERE x->>'product_id'=phys.product_id::text;
  IF after_qty IS DISTINCT FROM before_qty+phys.qty THEN RAISE EXCEPTION 'Receipt ma inny rzeczywisty stan magazynu' USING ERRCODE='23514';END IF;
 END LOOP;
 PERFORM return_assistant_physical_validate(a);PERFORM return_assistant_require(r.actor_id,r.api_key_id,true,false);PERFORM return_assistant_budget();RETURN NULL;
END $$;
CREATE FUNCTION return_assistant_seal() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$DECLARE j jsonb;k jsonb;a return_assistant_admissions;BEGIN
 IF TG_OP<>'INSERT' THEN j:=to_jsonb(OLD);END IF;IF TG_OP<>'DELETE' THEN k:=to_jsonb(NEW);END IF;
 FOR a IN SELECT ad.* FROM return_assistant_admissions ad WHERE ad.transaction_id=pg_current_xact_id() AND ad.tenant_id IN((j->>'tenant_id')::uuid,(k->>'tenant_id')::uuid) AND EXISTS(SELECT 1 FROM return_assistant_receipts r WHERE(r.tenant_id,r.id)=(ad.tenant_id,ad.receipt_id)) LOOP
  IF(TG_TABLE_NAME='return_cases' AND a.return_id IN((j->>'id')::uuid,(k->>'id')::uuid)) OR(TG_TABLE_NAME='return_items' AND a.return_id IN((j->>'return_id')::uuid,(k->>'return_id')::uuid)) OR(TG_TABLE_NAME='return_assistant_sessions' AND a.session_id IN((j->>'id')::uuid,(k->>'id')::uuid)) OR(TG_TABLE_NAME IN('orders') AND a.payload->'snapshot'->'order'->>'id' IN(j->>'id',k->>'id')) OR(TG_TABLE_NAME IN('order_items','payment_entries','documents','wms_operations','stock_movements') AND a.payload->'snapshot'->'order'->>'id' IN(j->>'order_id',k->>'order_id')) OR(TG_TABLE_NAME='packing_stations' AND a.payload->'snapshot'->'session'->>'station_id' IN(j->>'id',k->>'id')) OR(TG_TABLE_NAME='wms_policies') OR(TG_TABLE_NAME IN('stock_movements','wms_return_fragments') AND a.return_id::text IN(j->>'return_id',k->>'return_id')) OR(TG_TABLE_NAME IN('stock','stock_locations','stock_location_movements','wms_layer_positions','wms_layer_movements','wms_cost_layers','wms_issue_fragments') AND EXISTS(SELECT 1 FROM jsonb_array_elements(a.payload->'snapshot'->'lines')l CROSS JOIN LATERAL jsonb_array_elements(l->'components')c WHERE c->>'product_id' IN(j->>'product_id',k->>'product_id') AND(TG_TABLE_NAME IN('wms_cost_layers','wms_issue_fragments') OR a.payload->'snapshot'->'return_case'->>'warehouse_id' IN(j->>'warehouse_id',k->>'warehouse_id')))) THEN RAISE EXCEPTION 'Zatwierdzone przyjęcie asystenta jest zamknięte' USING ERRCODE='23514';END IF;
 END LOOP;IF TG_OP='DELETE' THEN RETURN OLD;END IF;RETURN NEW;
END $$;
-- Session update is performed before receipt so the same-TX seal also closes it.
CREATE CONSTRAINT TRIGGER return_assistant_receipt_complete AFTER INSERT ON return_assistant_receipts DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION return_assistant_complete();
CREATE CONSTRAINT TRIGGER return_assistant_admission_complete AFTER INSERT ON return_assistant_admissions DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION return_assistant_complete();
DO $$DECLARE rel text;BEGIN FOREACH rel IN ARRAY ARRAY['return_assistant_operations','return_assistant_photos','return_assistant_previews','return_assistant_receipts','return_assistant_admissions'] LOOP EXECUTE format('CREATE TRIGGER return_assistant_immutable BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION return_assistant_immutable()',rel);END LOOP;
 FOREACH rel IN ARRAY ARRAY['return_cases','return_items','return_assistant_sessions','orders','order_items','payment_entries','documents','packing_stations','wms_policies','stock_movements','wms_return_fragments','stock','stock_locations','stock_location_movements','wms_layer_positions','wms_layer_movements','wms_cost_layers','wms_issue_fragments','wms_operations'] LOOP EXECUTE format('CREATE TRIGGER return_assistant_seal BEFORE INSERT OR UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION return_assistant_seal()',rel);END LOOP;
END $$;
DO $$DECLARE f regprocedure;BEGIN FOR f IN SELECT p.oid::regprocedure FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname LIKE 'return_assistant_%' LOOP EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,dyna_app',f);END LOOP;END $$;
GRANT EXECUTE ON FUNCTION return_assistant_installed(),return_assistant_access(uuid,uuid,boolean,boolean),return_assistant_lock(),return_assistant_start(uuid,jsonb,uuid,uuid),return_assistant_step(uuid,text,jsonb,uuid,uuid,jsonb),return_assistant_preview(uuid,uuid,jsonb,uuid,uuid),return_assistant_prepare(uuid,uuid,jsonb,uuid,uuid),return_assistant_finish(uuid,uuid,uuid),return_assistant_photo_content(uuid,uuid,uuid) TO dyna_app;
CREATE FUNCTION return_assistant_guards() RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$DECLARE n integer;BEGIN
 IF EXISTS(SELECT 1 FROM unnest(ARRAY['return_assistant_sessions','return_assistant_operations','return_assistant_photos','return_assistant_previews','return_assistant_receipts','return_assistant_admissions'])u(name) WHERE to_regclass('public.'||u.name) IS NULL) THEN RETURN false;END IF;
 IF(SELECT count(*) FROM pg_class WHERE oid=ANY(ARRAY['return_assistant_sessions'::regclass,'return_assistant_operations'::regclass,'return_assistant_photos'::regclass,'return_assistant_previews'::regclass,'return_assistant_receipts'::regclass,'return_assistant_admissions'::regclass]) AND relrowsecurity AND relforcerowsecurity)<>6 THEN RETURN false;END IF;
 SELECT count(*) INTO n FROM pg_trigger tr WHERE NOT tr.tgisinternal AND tr.tgenabled IN('O','A') AND((tr.tgname='return_assistant_immutable' AND tr.tgfoid='return_assistant_immutable()'::regprocedure AND tr.tgrelid=ANY(ARRAY['return_assistant_operations'::regclass,'return_assistant_photos'::regclass,'return_assistant_previews'::regclass,'return_assistant_receipts'::regclass,'return_assistant_admissions'::regclass])) OR(tr.tgname='return_assistant_seal' AND tr.tgfoid='return_assistant_seal()'::regprocedure AND tr.tgrelid=ANY(ARRAY['return_cases'::regclass,'return_items'::regclass,'return_assistant_sessions'::regclass,'orders'::regclass,'order_items'::regclass,'payment_entries'::regclass,'documents'::regclass,'packing_stations'::regclass,'wms_policies'::regclass,'stock_movements'::regclass,'wms_return_fragments'::regclass,'stock'::regclass,'stock_locations'::regclass,'stock_location_movements'::regclass,'wms_layer_positions'::regclass,'wms_layer_movements'::regclass,'wms_cost_layers'::regclass,'wms_issue_fragments'::regclass,'wms_operations'::regclass])) OR(tr.tgname IN('return_assistant_receipt_complete','return_assistant_admission_complete') AND tr.tgfoid='return_assistant_complete()'::regprocedure AND tr.tgdeferrable AND tr.tginitdeferred));
 RETURN n=26 AND (SELECT count(*) FROM pg_constraint co WHERE co.conrelid=ANY(ARRAY['return_assistant_sessions'::regclass,'return_assistant_operations'::regclass,'return_assistant_photos'::regclass,'return_assistant_previews'::regclass,'return_assistant_receipts'::regclass,'return_assistant_admissions'::regclass]) AND co.contype='f' AND co.convalidated)=20 AND (SELECT count(*) FROM pg_trigger tr WHERE NOT tr.tgisinternal AND tr.tgenabled IN('O','A') AND tr.tgname='return_assistant_witness' AND tr.tgfoid=to_regprocedure('return_assistant_witness()') AND tr.tgrelid=ANY(ARRAY['stock_movements'::regclass,'stock_location_movements'::regclass,'wms_return_fragments'::regclass,'wms_layer_movements'::regclass,'wms_operations'::regclass]))=5 AND NOT has_column_privilege('dyna_app','return_assistant_previews','private_scope_nonce','SELECT') AND NOT has_column_privilege('dyna_app','return_assistant_sessions','lease_token_hash','SELECT') AND NOT has_column_privilege('dyna_app','return_assistant_photos','content_encrypted','SELECT') AND NOT has_table_privilege('dyna_app','return_assistant_admissions','SELECT') AND NOT EXISTS(SELECT 1 FROM pg_constraint co WHERE co.conrelid=ANY(ARRAY['return_assistant_sessions'::regclass,'return_assistant_operations'::regclass,'return_assistant_photos'::regclass,'return_assistant_previews'::regclass,'return_assistant_receipts'::regclass,'return_assistant_admissions'::regclass]) AND co.contype='f' AND NOT co.convalidated);
END $$;
REVOKE ALL ON FUNCTION return_assistant_guards() FROM PUBLIC;GRANT EXECUTE ON FUNCTION return_assistant_guards() TO dyna_app;
-- Private actual current-TX journal witness, not a browser/provider assertion.
CREATE FUNCTION return_assistant_witness() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$DECLARE j jsonb:=to_jsonb(NEW);a return_assistant_admissions;match_scope boolean;BEGIN
 FOR a IN SELECT ad.* FROM return_assistant_admissions ad WHERE ad.tenant_id=(j->>'tenant_id')::uuid AND ad.transaction_id=pg_current_xact_id() LOOP
  IF TG_TABLE_NAME IN('stock_movements','wms_return_fragments','wms_operations') THEN match_scope:=j->>'return_id'=a.return_id::text;
  ELSE match_scope:=j->>'warehouse_id'=a.payload->'snapshot'->'return_case'->>'warehouse_id' AND EXISTS(SELECT 1 FROM jsonb_array_elements(a.payload->'snapshot'->'lines')l CROSS JOIN LATERAL jsonb_array_elements(l->'components')c WHERE c->>'product_id'=j->>'product_id');END IF;
  IF match_scope THEN
   IF EXISTS(SELECT 1 FROM return_assistant_receipts rr WHERE(rr.tenant_id,rr.id)=(a.tenant_id,a.receipt_id)) THEN RAISE EXCEPTION 'Zatwierdzone przyjęcie asystenta jest zamknięte' USING ERRCODE='23514';END IF;
   UPDATE return_assistant_admissions SET witnesses=witnesses||jsonb_build_array(jsonb_build_object('table',TG_TABLE_NAME,'row',j)) WHERE(tenant_id,transaction_id,receipt_id)=(a.tenant_id,a.transaction_id,a.receipt_id);
  END IF;
 END LOOP;RETURN NEW;
END $$;
CREATE FUNCTION return_assistant_physical_validate(a return_assistant_admissions) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE t uuid:=a.tenant_id;wh uuid:=(a.payload->'snapshot'->'return_case'->>'warehouse_id')::uuid;oid uuid:=(a.payload->'snapshot'->'order'->>'id')::uuid;before_source jsonb:=a.payload->'snapshot'->'source';cur jsonb;wanted jsonb;bins jsonb;positions jsonb;actual jsonb;rec record;witness_row jsonb;live jsonb;picks jsonb:=coalesce(a.payload->'receive_input'->'wms_lots'->'picks','[]');wmson boolean:=a.payload->'snapshot'->'order'->'wms_lots_enabled'='true'::jsonb;BEGIN
 cur:=return_assistant_source(a.return_id);
 SELECT coalesce(jsonb_agg(jsonb_build_object('product_id',z.product_id,'quantity',z.qty) ORDER BY z.product_id),'[]') INTO wanted FROM(SELECT c->>'product_id' product_id,sum((c->>'quantity')::bigint*(d->>'restocked')::bigint) qty FROM jsonb_array_elements(a.payload->'snapshot'->'lines')l CROSS JOIN LATERAL jsonb_array_elements(l->'components')c JOIN LATERAL(SELECT value d FROM jsonb_array_elements(CASE WHEN a.payload->>'action'='receive' THEN a.payload->'receive_input'->'items' ELSE '[]'::jsonb END)x WHERE x->>'item_id'=l->>'item_id')z ON true GROUP BY c->>'product_id' HAVING sum((c->>'quantity')::bigint*(d->>'restocked')::bigint)>0)z;
 -- Witness records must still be their exact genuine inserted rows.
 FOR witness_row IN SELECT value FROM jsonb_array_elements(a.witnesses) LOOP
  IF witness_row->>'table' NOT IN('stock_movements','stock_location_movements','wms_return_fragments','wms_layer_movements','wms_operations') THEN RAISE EXCEPTION 'Nieznany świadek przyjęcia' USING ERRCODE='23514';END IF;
  EXECUTE format('SELECT to_jsonb(x) FROM %I x WHERE tenant_id=$1 AND id=$2',witness_row->>'table') INTO live USING t,(witness_row->'row'->>'id')::uuid;
  IF live IS DISTINCT FROM witness_row->'row' THEN RAISE EXCEPTION 'Dziennik przyjęcia zmienił rzeczywistą treść' USING ERRCODE='23514';END IF;
 END LOOP;
 SELECT coalesce(jsonb_agg(jsonb_build_object('product_id',w->'row'->>'product_id','quantity',(w->'row'->>'delta')::bigint) ORDER BY w->'row'->>'product_id'),'[]') INTO actual FROM jsonb_array_elements(a.witnesses)w WHERE w->>'table'='stock_movements';
 IF actual IS DISTINCT FROM wanted OR EXISTS(SELECT 1 FROM jsonb_array_elements(a.witnesses)w WHERE w->>'table'='stock_movements' AND(w->'row'->>'kind'<>'return' OR w->'row'->>'order_id' IS DISTINCT FROM oid::text OR w->'row'->>'warehouse_id' IS DISTINCT FROM wh::text OR w->'row'->>'return_id' IS DISTINCT FROM a.return_id::text)) THEN RAISE EXCEPTION 'Przyjęcie wymaga dokładnego rzeczywistego dziennika zwrotu' USING ERRCODE='23514';END IF;
 IF wmson AND jsonb_array_length(wanted)>0 THEN
  SELECT coalesce(jsonb_agg(jsonb_build_object('product_id',z.product_id,'location',z.location,'quantity',z.qty) ORDER BY z.product_id,z.location COLLATE "C"),'[]') INTO bins FROM(SELECT f.product_id::text product_id,p->>'location' location,sum((p->>'quantity')::bigint) qty FROM jsonb_array_elements(picks)p JOIN wms_issue_fragments f ON(f.tenant_id,f.id,f.order_id)=(t,(p->>'issue_fragment_id')::uuid,oid) GROUP BY f.product_id,p->>'location')z;
 ELSE SELECT coalesce(jsonb_agg(jsonb_build_object('product_id',x->>'product_id','location','ZWROT','quantity',x->'quantity') ORDER BY x->>'product_id'),'[]') INTO bins FROM jsonb_array_elements(wanted)x;END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('product_id',z.product_id,'location',z.location,'quantity',z.qty) ORDER BY z.product_id,z.location COLLATE "C"),'[]') INTO actual FROM(SELECT w->'row'->>'product_id' product_id,w->'row'->>'location' location,sum((w->'row'->>'delta')::bigint) qty FROM jsonb_array_elements(a.witnesses)w WHERE w->>'table'='stock_location_movements' GROUP BY w->'row'->>'product_id',w->'row'->>'location')z;
 IF actual IS DISTINCT FROM bins OR EXISTS(SELECT 1 FROM jsonb_array_elements(a.witnesses)w WHERE w->>'table'='stock_location_movements' AND(w->'row'->>'kind'<>'stock_in' OR(w->'row'->>'delta')::bigint<=0)) THEN RAISE EXCEPTION 'Przyjęcie wymaga dokładnego dziennika lokalizacji' USING ERRCODE='23514';END IF;
 FOR rec IN SELECT coalesce(c->>'product_id',b->>'product_id') product_id,coalesce(c->>'location',b->>'location') location,coalesce((b->>'quantity')::bigint,0) before_qty,coalesce((c->>'quantity')::bigint,0) after_qty,b,c FROM jsonb_array_elements(before_source->'stock_bins')b FULL JOIN jsonb_array_elements(cur->'stock_bins')c ON(b->>'product_id',b->>'location')=(c->>'product_id',c->>'location') LOOP
  IF rec.c IS NULL OR(rec.b IS NULL AND rec.after_qty<=0) OR(rec.b IS NOT NULL AND (rec.b-'quantity') IS DISTINCT FROM(rec.c-'quantity')) OR rec.after_qty-rec.before_qty IS DISTINCT FROM coalesce((SELECT (v->>'quantity')::bigint FROM jsonb_array_elements(bins)v WHERE(v->>'product_id',v->>'location')=(rec.product_id,rec.location)),0) THEN RAISE EXCEPTION 'Przyjęcie ma inną zmianę lokalizacji' USING ERRCODE='23514';END IF;
 END LOOP;
 FOR rec IN SELECT x FROM jsonb_array_elements(before_source->'stock')x LOOP
  SELECT x INTO actual FROM jsonb_array_elements(cur->'stock')x WHERE x->>'product_id'=rec.x->>'product_id';
  IF((rec.x->'value')-ARRAY['on_hand','available','version','updated_at']) IS DISTINCT FROM((actual->'value')-ARRAY['on_hand','available','version','updated_at']) AND rec.x->'value' IS DISTINCT FROM 'null'::jsonb THEN RAISE EXCEPTION 'Przyjęcie zmieniło rezerwację' USING ERRCODE='23514';END IF;
 END LOOP;
 IF wmson AND jsonb_array_length(wanted)>0 THEN
  IF cur->>'layers_hash' IS DISTINCT FROM before_source->>'layers_hash' THEN RAISE EXCEPTION 'Zwrot zmienił historyczne koszty warstw' USING ERRCODE='23514';END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object('issue_fragment_id',w->'row'->>'issue_fragment_id','location',w->'row'->>'location','quantity',(w->'row'->>'quantity')::bigint) ORDER BY w->'row'->>'issue_fragment_id',w->'row'->>'location'),'[]') INTO actual FROM jsonb_array_elements(a.witnesses)w WHERE w->>'table'='wms_return_fragments';
  IF actual IS DISTINCT FROM(SELECT coalesce(jsonb_agg(jsonb_build_object('issue_fragment_id',p->>'issue_fragment_id','location',p->>'location','quantity',(p->>'quantity')::bigint) ORDER BY p->>'issue_fragment_id',p->>'location'),'[]') FROM jsonb_array_elements(picks)p) OR(SELECT count(*) FROM jsonb_array_elements(a.witnesses)w WHERE w->>'table'='wms_operations')<>1 THEN RAISE EXCEPTION 'Zwrot wymaga rzeczywistych fragmentów WMS' USING ERRCODE='23514';END IF;
  FOR witness_row IN SELECT value->'row' FROM jsonb_array_elements(a.witnesses) WHERE value->>'table'='wms_return_fragments' LOOP
   SELECT jsonb_build_object('layer_id',f.layer_id,'product_id',f.product_id,'value_minor',CASE WHEN f.unit_cost_minor IS NULL THEN NULL ELSE f.unit_cost_minor*(witness_row->>'quantity')::bigint END) INTO live FROM wms_issue_fragments f WHERE(f.tenant_id,f.id,f.order_id)=(t,(witness_row->>'issue_fragment_id')::uuid,oid);
   IF(witness_row->'layer_id',witness_row->'product_id',witness_row->'value_minor') IS DISTINCT FROM(live->'layer_id',live->'product_id',live->'value_minor') OR witness_row->>'warehouse_id' IS DISTINCT FROM wh::text OR witness_row->>'return_id' IS DISTINCT FROM a.return_id::text THEN RAISE EXCEPTION 'Koszt lub pochodzenie fragmentu zwrotu jest inne' USING ERRCODE='23514';END IF;
  END LOOP;
  SELECT coalesce(jsonb_agg(jsonb_build_object('product_id',z.product_id,'layer_id',z.layer_id,'location',z.location,'quantity',z.qty) ORDER BY z.product_id,z.layer_id,z.location COLLATE "C"),'[]') INTO positions FROM(SELECT f.product_id::text product_id,f.layer_id::text layer_id,p->>'location' location,sum((p->>'quantity')::bigint) qty FROM jsonb_array_elements(picks)p JOIN wms_issue_fragments f ON(f.tenant_id,f.id,f.order_id)=(t,(p->>'issue_fragment_id')::uuid,oid) GROUP BY f.product_id,f.layer_id,p->>'location')z;
  SELECT coalesce(jsonb_agg(jsonb_build_object('product_id',z.product_id,'layer_id',z.layer_id,'location',z.location,'quantity',z.qty) ORDER BY z.product_id,z.layer_id,z.location COLLATE "C"),'[]') INTO actual FROM(SELECT w->'row'->>'product_id' product_id,w->'row'->>'layer_id' layer_id,w->'row'->>'location' location,sum((w->'row'->>'delta')::bigint) qty FROM jsonb_array_elements(a.witnesses)w WHERE w->>'table'='wms_layer_movements' GROUP BY w->'row'->>'product_id',w->'row'->>'layer_id',w->'row'->>'location')z;
  IF actual IS DISTINCT FROM positions THEN RAISE EXCEPTION 'Zwrot wymaga dokładnego rzeczywistego dziennika warstw' USING ERRCODE='23514';END IF;
  FOR rec IN SELECT coalesce(c->>'product_id',b->>'product_id') product_id,coalesce(c->>'layer_id',b->>'layer_id') layer_id,coalesce(c->>'location',b->>'location') location,coalesce((b->>'quantity')::bigint,0) before_qty,coalesce((c->>'quantity')::bigint,0) after_qty,b,c FROM jsonb_array_elements(before_source->'positions')b FULL JOIN jsonb_array_elements(cur->'positions')c ON(b->>'product_id',b->>'layer_id',b->>'location')=(c->>'product_id',c->>'layer_id',c->>'location') LOOP
   IF rec.c IS NULL OR(rec.b IS NULL AND rec.after_qty<=0) OR(rec.b IS NOT NULL AND(rec.b-ARRAY['quantity','version']) IS DISTINCT FROM(rec.c-ARRAY['quantity','version'])) OR (rec.c->>'version')::bigint IS DISTINCT FROM coalesce((rec.b->>'version')::bigint,0)+(SELECT count(*) FROM jsonb_array_elements(picks)pi JOIN wms_issue_fragments fi ON(fi.tenant_id,fi.id)=(t,(pi->>'issue_fragment_id')::uuid) WHERE(fi.product_id::text,fi.layer_id::text,pi->>'location')=(rec.product_id,rec.layer_id,rec.location)) OR rec.after_qty-rec.before_qty IS DISTINCT FROM coalesce((SELECT (v->>'quantity')::bigint FROM jsonb_array_elements(positions)v WHERE(v->>'product_id',v->>'layer_id',v->>'location')=(rec.product_id,rec.layer_id,rec.location)),0) THEN RAISE EXCEPTION 'Zwrot ma inne rzeczywiste pozycje warstw' USING ERRCODE='23514';END IF;
  END LOOP;
 ELSE IF cur->'positions' IS DISTINCT FROM before_source->'positions' OR cur->>'layers_hash' IS DISTINCT FROM before_source->>'layers_hash' OR EXISTS(SELECT 1 FROM jsonb_array_elements(a.witnesses)w WHERE w->>'table' IN('wms_return_fragments','wms_layer_movements','wms_operations')) THEN RAISE EXCEPTION 'Zwrot bez restock WMS nie może tworzyć dziennika partii' USING ERRCODE='23514';END IF;END IF;
END $$;
REVOKE ALL ON FUNCTION return_assistant_witness(),return_assistant_physical_validate(return_assistant_admissions) FROM PUBLIC,dyna_app;
DO $$DECLARE rel text;BEGIN FOREACH rel IN ARRAY ARRAY['stock_movements','stock_location_movements','wms_return_fragments','wms_layer_movements','wms_operations'] LOOP EXECUTE format('CREATE TRIGGER return_assistant_witness AFTER INSERT ON %I FOR EACH ROW EXECUTE FUNCTION return_assistant_witness()',rel);END LOOP;END $$;
